const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const houston = ee.Geometry.Point([-95.3698, 29.7604]);
  const aoi = houston.buffer(20000); // 20km buffer around Houston center
  const collectionId = 'NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG';
  const band = 'avg_rad';
  const aprilDate = '2024-04-01';
  const mayDate = '2024-05-01';

  try {
    // 2. Data Acquisition
    const aprilCollection = ee.ImageCollection(collectionId)
      .filterDate(aprilDate, ee.Date(aprilDate).advance(1, 'month'))
      .select(band);

    const mayCollection = ee.ImageCollection(collectionId)
      .filterDate(mayDate, ee.Date(mayDate).advance(1, 'month'))
      .select(band);

    // 3. Data Availability Check
    const aprilSize = await aprilCollection.size().getInfo();
    const maySize = await mayCollection.size().getInfo();

    if (aprilSize === 0 || maySize === 0) {
      console.log(`Image availability: April 2024 (${aprilSize}), May 2024 (${maySize}).`);
      console.log('VIIRS monthly data for one or both periods is not yet available.');
      console.log('A');
      return;
    }

    const aprilImage = aprilCollection.first();
    const mayImage = mayCollection.first();

    // 4. Processing & Pixel Count Validation
    const scale = 1000;
    const aprilStats = aprilImage.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9
    });

    const mayStats = mayImage.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9
    });

    const [aprilResult, mayResult] = await Promise.all([
        ee.data.computeValue(aprilStats),
        ee.data.computeValue(mayStats)
    ]);

    const aprilMean = aprilResult[`${band}_mean`];
    const aprilCount = aprilResult[`${band}_count`];
    const mayMean = mayResult[`${band}_mean`];
    const mayCount = mayResult[`${band}_count`];

    if (aprilCount === 0 || mayCount === 0) {
        console.log(`Valid pixels: April 2024 (${aprilCount}), May 2024 (${mayCount}).`);
        console.log('No valid pixels found in the area of interest after processing.');
        console.log('C2');
        return;
    }

    if (aprilMean === null || mayMean === null || isNaN(aprilMean) || isNaN(mayMean)) {
        console.log(`Calculation failed: April Mean (${aprilMean}), May Mean (${mayMean}).`);
        console.log('Could not compute a valid mean value.');
        console.log('C3');
        return;
    }

    // 5. Comparison and Final Answer
    console.log(`April 2024 Avg Intensity: ${aprilMean.toFixed(2)} (from ${aprilCount} pixels)`);
    console.log(`May 2024 Avg Intensity: ${mayMean.toFixed(2)} (from ${mayCount} pixels)`);
    console.log('NOTE: Monthly data used as proxy for the specified date.');

    if (mayMean < aprilMean) {
        console.log('A');
    } else {
        console.log('B');
    }

  } catch (error) {
    console.error('An error occurred during the analysis:');
    console.error(error);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
